          "Cu antetul încă activ, deruleaza în jos sau click în zona de subsol",
          "Sau mergi la Insert > Page Number > Bottom of Page",
          "Alege stilul 'Plain Number 2' (centrat) sau 'Plain Number 3' (dreapta)",
          "Observa ca fiecare pagină are acum numarul ei automat"
        ],
        "teacher_support": "Arată diferitele stiluri disponibile, explică ca numarul se actualizează singur"
      },
      {
        "task": "Iesi din modul antet/subsol și verifică",
        "steps": [
          "Dublu-click în zona de text principal (mijlocul paginii)",
          "Sau apasă butonul 'Close Header and Footer' din bara",
          "Deruleaza prin document și verifică: antetul și numarul apar pe toate paginile",
          "Adaugă încă o pagină (Enter de mai multe ori) - verifică ca se numeroteaza automat"
        ],
        "teacher_support": "Subliniaza ca antetul/subsolul sunt acum 'gri' dar vor aparea la printare"
      }
    ],
    "success_criteria": [
      "Elevul poate adaugă un antet cu text",
      "Elevul poate adaugă numere de pagină în subsol",
      "Elevul poate iesi din modul de editare antet/subsol",
      "Elevul înțelege ca elementele apar pe toate paginile"
    ]
  },
  "practice_independent": {
    "duration_minutes": 15,
    "levels": {
      "minim": [
        {
          "task": "Deschide un document cu 2 pagini. Adaugă numere de pagină în subsol, centrate.",
          "expected_output": "Document cu numere de pagină vizibile pe ambele pagini"
        }
      ],
      "standard": [
        {
          "task": "Creaza un mini-referat de 3 pagini cu: antet continand 'Numele tau - Informatică' aliniat dreapta, subsol cu numarul paginii centrat și data curenta aliniata stanga.",
          "expected_output": "Referat cu antet personalizat și subsol cu numar + data"
        }
      ],
      "performanta": [
        {
          "task": "Creaza un document de 4 pagini: prima pagină să fie pagină de titlu (fara numar și fara antet folosind 'Different First Page'), paginile 2-4 cu antet 'Capitolul X' și numere de pagină incepand de la 1 (nu de la 2). Salvează ca 'Referat_complet.docx'.",
          "expected_output": "Document cu prima pagină speciala și numerotare corectă de la 1 pe paginile de continut"
        }
      ]
    }
  },
  "wrap_up": {
    "duration_minutes": 7,
    "exit_ticket": {
      "minim": [
        "Unde apare antetul pe pagină?"
      ],
      "standard": [
        "De ce folosim numere de pagină automate în loc să scriem manual '1', '2', '3'?"
      ],
      "performanta": [
        "Cum faci prima pagină fara numar de pagină, dar restul cu numere?"
      ]
    },
    "preview_next": "Saptamana viitoare facem recapitulare și evaluare pentru tot ce am învățat la procesarea textului!"
  }
